import{_ as t,o,c as s,ah as i}from"./chunks/framework.B_HCLbdO.js";const a="/projects/WonderEcho/en/latest/assets/image1.C76lwX8B.png",n="/projects/WonderEcho/en/latest/assets/image2.XYPOHZjO.png",r="/projects/WonderEcho/en/latest/assets/image3.BuvMAlB6.png",l="/projects/WonderEcho/en/latest/assets/image4.B7qvHNLD.png",c="/projects/WonderEcho/en/latest/assets/image5.DrHF5fEr.png",h="/projects/WonderEcho/en/latest/assets/image6.ByQz8tIY.png",d="/projects/WonderEcho/en/latest/assets/image7.BW2EGrrH.png",m="/projects/WonderEcho/en/latest/assets/image8.CSjhLoG9.png",g="/projects/WonderEcho/en/latest/assets/image9.BwhVsC_u.png",p="/projects/WonderEcho/en/latest/assets/image10.Cj3Jpv9F.png",w="/projects/WonderEcho/en/latest/assets/image11.DsnXKVH3.png",u="/projects/WonderEcho/en/latest/assets/image12.BM9Tn-Hv.png",f="/projects/WonderEcho/en/latest/assets/image13.D1PvoedT.png",A="/projects/WonderEcho/en/latest/assets/image14.BQmnu_6o.png",y="/projects/WonderEcho/en/latest/assets/image15.DrHBWq5i.png",b="/projects/WonderEcho/en/latest/assets/image16.BTp0g-Fl.png",v="/projects/WonderEcho/en/latest/assets/image17.lCAnzvJ2.png",E="/projects/WonderEcho/en/latest/assets/image18.CjxQ-JSR.png",x="/projects/WonderEcho/en/latest/assets/image19.vx_1JCO7.png",_="/projects/WonderEcho/en/latest/assets/image20.CnoWXAcG.png",T="/projects/WonderEcho/en/latest/assets/image22.D--tGVyy.png",P="/projects/WonderEcho/en/latest/assets/image23.Dgichlul.png",C="/projects/WonderEcho/en/latest/assets/image24.CbxtAJoA.png",j="/projects/WonderEcho/en/latest/assets/image25.d2-n8aCd.png",z="/projects/WonderEcho/en/latest/assets/image26.DtlO1Gc3.png",W="data:image/png;base64,",D="/projects/WonderEcho/en/latest/assets/image28.B15tYt-d.png",k="/projects/WonderEcho/en/latest/assets/image29.B7Gh4350.png",F="/projects/WonderEcho/en/latest/assets/image30.DaIQ-amz.png",q="/projects/WonderEcho/en/latest/assets/image31.CKL3hpL5.png",I="/projects/WonderEcho/en/latest/assets/image32.ByosvaPa.png",S="data:image/png;base64,",V="/projects/WonderEcho/en/latest/assets/image1.DfcQidS6.png",B="/projects/WonderEcho/en/latest/assets/image2.DCTUhLvA.png",K="/projects/WonderEcho/en/latest/assets/image3.J46rQCDD.png",R="/projects/WonderEcho/en/latest/assets/image4.DqcteY2u.png",N="/projects/WonderEcho/en/latest/assets/image1.C8Q_lTl7.png",O="/projects/WonderEcho/en/latest/assets/image2.B5pJB_TT.png",H="/projects/WonderEcho/en/latest/assets/image3.B50MVOQo.png",G="/projects/WonderEcho/en/latest/assets/image4.O6azn1PI.png",L="/projects/WonderEcho/en/latest/assets/image5.Bhrz1B-J.png",Q="/projects/WonderEcho/en/latest/assets/image4.DqcteY2u.png",X="/projects/WonderEcho/en/latest/assets/image1.BjJJy-4C.png",J="/projects/WonderEcho/en/latest/assets/image2.CvYyBEdw.png",Z="/projects/WonderEcho/en/latest/assets/image3.CDsyrlVO.png",U="/projects/WonderEcho/en/latest/assets/image4.F3Il44MV.png",M="/projects/WonderEcho/en/latest/assets/image4.DqcteY2u.png",ne=JSON.parse('{"title":"5. Firmware Development","description":"","frontmatter":{},"headers":[],"relativePath":"docs/5_Firmware_Development.md","filePath":"docs/5_Firmware_Development.md"}'),Y={name:"docs/5_Firmware_Development.md"};function $(ee,e,te,oe,se,ie){return o(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="_5-firmware-development" tabindex="-1">5. Firmware Development <a class="header-anchor" href="#_5-firmware-development" aria-label="Permalink to &quot;5. Firmware Development&quot;">​</a></h1><p id="p5-1"></p><h2 id="_5-1-wonderecho-firmware-development" tabindex="-1">5.1 WonderEcho Firmware Development <a class="header-anchor" href="#_5-1-wonderecho-firmware-development" aria-label="Permalink to &quot;5.1 WonderEcho Firmware Development&quot;">​</a></h2><p>This lesson covers the creation and flashing of firmware for the WonderEcho module.</p><h3 id="_5-1-1-notification" tabindex="-1">5.1.1 Notification <a class="header-anchor" href="#_5-1-1-notification" aria-label="Permalink to &quot;5.1.1 Notification&quot;">​</a></h3><p>The module comes pre-programmed with speech recognition firmware from the factory. This factory firmware file is available within the same directory as this document. Follow the provided instructions to rebuild the firmware if custom creation is necessary.</p><h3 id="_5-1-2-firmware-creation-and-flashing" tabindex="-1">5.1.2 Firmware Creation and Flashing <a class="header-anchor" href="#_5-1-2-firmware-creation-and-flashing" aria-label="Permalink to &quot;5.1.2 Firmware Creation and Flashing&quot;">​</a></h3><ol><li><p>Navigate to the official firmware creation website at <a href="https://aiplatform.chipintelli.com/home/index.html" target="_blank" rel="noreferrer">https://aiplatform.chipintelli.com/home/index.html</a>. The platform interface defaults to Chinese, so utilization of the browser translation feature is recommended to switch the language to English for easier navigation.</p></li><li><p>Access the ChipIntelli Voice AI Platform, click <strong>Platform Features</strong> in the top menu, and select <strong>In-depth development of product Firmware &amp; SDK</strong> under the Product Development section.</p></li></ol><img loading="lazy" height="538" width="1751" src="'+a+'" style="width:800px;" class="common_img"><ol start="3"><li><p>A login prompt will appear. Since standard registration requires a specific regional mobile number, a shared account is provided for international developers:</p><p><strong>Username: 18033085495<br> Password: hiwonder</strong></p></li><li><p>Upon successful login, click <strong>Offline speech recognition large model application</strong> to enter the development section.</p></li></ol><img loading="lazy" height="677" width="1180" src="'+n+'" style="width:800px;" class="common_img"><ol start="5"><li>Click <strong>Speech recognition firmware and SDK development</strong> in the submenu to access the corresponding section.</li></ol><img loading="lazy" height="572" width="1222" src="'+r+'" style="width:800px;" class="common_img"><ol start="6"><li>Click <strong>New projects</strong> in the left sidebar to initialize a new project.</li></ol><img loading="lazy" height="300" width="1047" src="'+l+'" style="width:800px;" class="common_img"><ol start="7"><li>Input a customized Product Name and Description. For the remaining fields, apply the options indicated by the red box, specifically selecting <strong>General</strong> and then <strong>Intelligent central control</strong> for the Product Type. Click <strong>Create</strong> once these configurations are complete.</li></ol><img loading="lazy" height="485" width="939" src="'+c+'" style="width:800px;" class="common_img"><img loading="lazy" height="504" width="949" src="'+h+'" style="width:800px;" class="common_img"><img loading="lazy" height="314" width="951" src="'+d+'" style="width:800px;" class="common_img"><img loading="lazy" height="376" width="947" src="'+m+'" style="width:800px;" class="common_img"><img loading="lazy" height="414" width="945" src="'+g+'" style="width:800px;" class="common_img"><img loading="lazy" height="407" width="949" src="'+p+'" style="width:800px;" class="common_img"><ol start="8"><li>Set the project language next. Select <strong>English</strong> under Language Type to configure English voice recognition. Click <strong>Continue</strong> to proceed after selecting the appropriate options.</li></ol><img loading="lazy" height="521" width="916" src="'+w+'" style="width:800px;" class="common_img"><img loading="lazy" height="590" width="969" src="'+u+'" style="width:800px;" class="common_img"><img loading="lazy" height="557" width="911" src="'+f+'" style="width:800px;" class="common_img"><ol start="9"><li>Important adjustments are required within the firmware configuration interface. Begin by enabling the <strong>Echo Cancellation</strong> feature under Algorithm Settings.</li></ol><img loading="lazy" height="352" width="1008" src="'+A+'" style="width:800px;" class="common_img"><ol start="10"><li>Set the oscillator source to <strong>Internal RC</strong> and disable the <strong>Baud Rate Calibration</strong> function under Hardware Settings.</li></ol><img loading="lazy" height="313" width="1017" src="'+y+'" style="width:800px;" class="common_img"><img loading="lazy" height="285" width="1078" src="'+b+'" style="width:800px;" class="common_img"><img loading="lazy" height="291" width="958" src="'+v+'" style="width:800px;" class="common_img"><ol start="11"><li>Configure <strong>UART0</strong> to <strong>Open-Drain Mode</strong> within the UART Print Settings, ensuring support for an external 5V pull-up.</li></ol><img loading="lazy" height="251" width="945" src="'+E+'" style="width:800px;" class="common_img"><ol start="12"><li>For Communication UART Settings, set the Baud Rate to 115200 and configure UART1 to Open-Drain Mode, also supporting external 5V pull-up. After adjusting these settings, click <strong>Continue</strong> to move forward.</li></ol><img loading="lazy" height="603" width="942" src="'+x+'" style="width:800px;" class="common_img"><ol start="13"><li>The subsequent step involves command word configuration. A voice output must be selected for the wake-up command. Select <strong>Dane - English Male Voice</strong> as the output voice for this example. The choice between Chinese and English voices depends entirely on the language settings configured previously.</li></ol><img loading="lazy" height="273" width="1108" src="'+_+'" style="width:800px;" class="common_img"><ol start="14"><li>Upload the command word attachment by locating the file named <strong>Command Phrase and Playback Protocol List</strong> and dragging it directly onto the webpage.</li></ol><img loading="lazy" height="743" width="1583" src="'+T+'" style="width:800px;" class="common_img"><ol start="15"><li>The command data populates the table below automatically after the file uploads.</li></ol><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The English firmware version exclusively supports English wake words, and mixed-language wake words are invalid. Furthermore, English wake words must be written in uppercase letters to ensure proper functionality.</strong></p></div><img loading="lazy" height="506" width="826" src="'+P+'" style="width:800px;" class="common_img"><ol start="16"><li>Enable <strong>switching Self-learning</strong> and select <strong>Designated study</strong>. The system automatically generates four self-learning commands, which require no changes during this step.</li></ol><img loading="lazy" height="653" width="1023" src="'+C+'" style="width:800px;" class="common_img"><ol start="17"><li>Click <strong>Submit now</strong> and allow a few minutes for the firmware generation process to complete. Click <strong>Download</strong> once finished to obtain the customized firmware.</li></ol><img loading="lazy" height="108" width="1780" src="'+j+'" style="width:800px;" class="common_img"><img loading="lazy" height="139" width="1832" src="'+z+'" style="width:800px;" class="common_img"><ol start="18"><li>Extract the downloaded archive. The resulting folder contains a .bin file, representing the custom firmware generated from the uploaded <strong>Command Phrase and Playback Protocol List</strong> file. Proceed to the <strong>5.1.3 Firmware Flashing</strong> section in this document to deploy the firmware to the module.</li></ol><img loading="lazy" height="56" width="397" src="'+W+'" style="width:800px;" class="common_img"><img loading="lazy" height="170" width="874" src="'+D+'" style="width:800px;" class="common_img"><h3 id="_5-1-3-firmware-flashing" tabindex="-1">5.1.3 Firmware Flashing <a class="header-anchor" href="#_5-1-3-firmware-flashing" aria-label="Permalink to &quot;5.1.3 Firmware Flashing&quot;">​</a></h3><ol><li>Connect the voice interaction module to the computer using a Type-C data cable.</li></ol><img loading="lazy" height="883" width="1266" src="'+k+'" style="width:800px;" class="common_img"><ol start="2"><li>Launch <a href="https://drive.google.com/drive/folders/1oxdaycGexBoikc8kI1Ha2SbNEz4KksHT?usp=sharing" target="_blank" rel="noreferrer">Firmware Development Tool\\PACK_UPDATE_TOOL.exe</a> located within the same directory as this document, choose the <strong>CI1302</strong> chip, and click <strong>Update</strong>.</li></ol><img loading="lazy" height="492" width="652" src="'+F+'" style="width:800px;" class="common_img"><ol start="3"><li>Click <strong>Select firmware</strong>, then locate the .bin firmware created in the previous steps. Here, the factory firmware <strong>CI1302_English_SingleMic_V00729_UART1_115200_2M.bin</strong> in the same directory as this document is used as an example.</li></ol><img loading="lazy" height="168" width="883" src="'+q+'" style="width:800px;" class="common_img"><ol start="4"><li>Locate the appropriate serial port and select it.</li></ol><img loading="lazy" height="844" width="1213" src="'+I+'" style="width:800px;" class="common_img"><ol start="5"><li>Press the <strong>RST</strong> button on the voice interaction module to enter flashing mode, then wait for the process to complete successfully.</li></ol><img loading="lazy" height="49" width="834" src="'+S+'" style="width:800px;" class="common_img"><h2 id="_5-2-modifying-functional-phrase-entries" tabindex="-1">5.2 Modifying Functional Phrase Entries <a class="header-anchor" href="#_5-2-modifying-functional-phrase-entries" aria-label="Permalink to &quot;5.2 Modifying Functional Phrase Entries&quot;">​</a></h2><p>The procedure for modifying functional phrase entries is outlined below.</p><ol><li><p>Open the <strong>Command Phrase and Playback Protocol List</strong> spreadsheet located in the same directory as this document.</p></li><li><p>Locate the functional phrase entries in the spreadsheet, which correspond to the first 10 items. These initial 10 functional phrases are fixed entries that do not support additions, meaning only modifications are permitted.</p></li></ol><img loading="lazy" height="306" width="1562" src="'+V+'" style="width:800px;" class="common_img"><ol start="3"><li>As an example, modify the wake word response phrase. Originally, the module plays back <strong>I&#39;m here</strong> when <strong>HELLO-HI-WONDER</strong> is recognized. Change the playback phrase to <strong>Hiwonder is here</strong>.</li></ol><img loading="lazy" height="307" width="1562" src="'+B+'" style="width:800px;" class="common_img"><ol start="4"><li>The wake word itself is also customizable. For example, set the wake word to <strong>HELLO-ROBOT</strong> and configure the module to play back <strong>I&#39;m here</strong> upon activation.</li></ol><img loading="lazy" height="308" width="1562" src="'+K+'" style="width:800px;" class="common_img"><ol start="5"><li>Save the spreadsheet after completing the modifications. Follow the steps detailed in <a href="#p5-1">5.1 WonderEcho Firmware Development</a> to upload the spreadsheet to the website. If firmware was created previously, click <strong>Inheritance</strong> within the existing project to reuse the configuration and bypass parameter setup.</li></ol><img loading="lazy" height="85" width="1789" src="'+R+'" style="width:800px;" class="common_img"><ol start="6"><li>Rebuild the firmware and flash it to the voice interaction module to apply the updated functional phrase entries.</li></ol><h2 id="_5-3-adding-new-command-words" tabindex="-1">5.3 Adding New Command Words <a class="header-anchor" href="#_5-3-adding-new-command-words" aria-label="Permalink to &quot;5.3 Adding New Command Words&quot;">​</a></h2><p>The procedure for adding new command words is outlined below.</p><ol><li><p>Open the <strong>Command Phrase and Playback Protocol List</strong> spreadsheet located in the same directory as this document.</p></li><li><p>Add a new command word at the bottom of the spreadsheet, such as <strong>SHOW-RED-LIGHT</strong>.</p></li></ol><img loading="lazy" height="144" width="1665" src="'+N+'" style="width:800px;" class="common_img"><ol start="3"><li><p>Set the function type to <strong>Command Word</strong> and the playback mode to <strong>Auto</strong>. This ensures that when <strong>SHOW-RED-LIGHT</strong> is recognized, the module will automatically play back <strong>It&#39;s a red light now</strong>.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>In the spreadsheet, select “命令词” for command word type and “主” for auto mode.</strong></p></div></li></ol><img loading="lazy" height="141" width="1666" src="'+O+'" style="width:800px;" class="common_img"><ol start="4"><li>Review the sending protocol. The first and second bytes form the data frame header and require no modification. For command words, the third byte must be set to <strong>00</strong> to distinguish between a command word and a playback phrase.</li></ol><img loading="lazy" height="140" width="1668" src="'+H+'" style="width:800px;" class="common_img"><ol start="5"><li>The fourth byte represents the command word ID in hexadecimal. If the previous command word ID was B4, this new command word should be assigned B5. In special cases, IDs can be duplicated when two command words need to produce the same result.</li></ol><img loading="lazy" height="223" width="1667" src="'+G+'" style="width:800px;" class="common_img"><ol start="6"><li>The fifth byte in the protocol is fixed at “FB” and does not require modification. Ensure that the sending and receiving protocols match in the spreadsheet.</li></ol><img loading="lazy" height="168" width="1667" src="'+L+'" style="width:800px;" class="common_img"><ol start="7"><li>Save the spreadsheet after implementing these changes. Follow the steps in <a href="#p5-1">5.1 WonderEcho Firmware Creation</a> to upload the spreadsheet to the platform. If firmware was generated previously, click <strong>Inheritance</strong> in the existing project to reuse the configuration and skip parameter setup.</li></ol><blockquote><img loading="lazy" height="85" width="1789" src="'+Q+'" style="width:800px;" class="common_img"></blockquote><ol start="8"><li>Rebuild the firmware and flash it to the voice interaction module to deploy the new command word functionality.</li></ol><h2 id="_5-4-adding-new-playback-phrases" tabindex="-1">5.4 Adding New Playback Phrases <a class="header-anchor" href="#_5-4-adding-new-playback-phrases" aria-label="Permalink to &quot;5.4 Adding New Playback Phrases&quot;">​</a></h2><p>The procedure for adding new playback phrases is outlined below.</p><ol><li><p>Open the <strong>Command Word and Playback Protocol List</strong> spreadsheet located in the same directory as this document.</p></li><li><p>Add a new entry at the bottom of the spreadsheet, such as the playback phrase <strong>It&#39;s a green light now</strong>.</p></li></ol><img loading="lazy" height="114" width="1665" src="'+X+'" style="width:800px;" class="common_img"><ol start="3"><li><p>Set the function type to <strong>Playback Phrase</strong> and the playback mode to <strong>Passive</strong>.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>Note that 播报语 must be selected for the playback phrase type and 被 for the passive mode within the spreadsheet.</strong></p></div></li></ol><img loading="lazy" height="168" width="1671" src="'+J+'" style="width:800px;" class="common_img"><ol start="4"><li>Review the sending protocol. The first and second bytes represent the data frame header and require no modification. For playback phrases, the third byte must be set to <strong>FF</strong> to classify the instruction specifically as a playback phrase.</li></ol><img loading="lazy" height="169" width="1671" src="'+Z+'" style="width:800px;" class="common_img"><ol start="5"><li><p>The fourth byte represents the command word or playback phrase ID in hexadecimal. If the previous playback phrase ID was <strong>2E</strong>, this new phrase must be assigned <strong>2F</strong>.</p></li><li><p>The fifth byte in the protocol is fixed at <strong>FB</strong> and requires no modification. Ensure the sending and receiving protocols match exactly within the spreadsheet.</p></li></ol><img loading="lazy" height="168" width="1667" src="'+U+'" style="width:800px;" class="common_img"><ol start="7"><li>Save the spreadsheet after applying these changes. Follow the steps in <a href="#p5-1">5.1 WonderEcho Firmware Creation</a> to upload the spreadsheet to the website. If firmware was developed previously, click <strong>Inheritance</strong> in the existing project to reuse the configuration and skip parameter setup.</li></ol><img loading="lazy" height="85" width="1789" src="'+M+'" style="width:800px;" class="common_img"><ol start="8"><li>Rebuild the firmware and flash it to the voice interaction module to enable the new playback phrase functionality.</li></ol>',101)])])}const re=t(Y,[["render",$]]);export{ne as __pageData,re as default};
